#!/usr/bin/env bash
# open-telemetry/opentelemetry-operator 0.114.0 - preset: no-crds
# Path: render this preset locally, then upload the objects to your
# ConfigHub Space as Units you can edit, diff, and deliver.
# Needs a ConfigHub account: run cub auth login once before this script.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this preset. Chart page: https://confighub.github.io/helm-expt/site/charts/open-telemetry-opentelemetry-operator-0-114-0.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install it with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

SPACE="${CUB_SPACE:-helm-opentelemetry-operator-no-crds}"

say "Check ConfigHub auth"
if ! cub auth status >/dev/null 2>&1; then
  printf 'Not logged in. Run: cub auth login\nThen re-run this script.\n' >&2
  exit 1
fi

say "Render the no-crds preset into ./open-telemetry-opentelemetry-operator-0-114-0-no-crds"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/open-telemetry-opentelemetry-operator:0.114.0 --base no-crds --work-dir ./open-telemetry-opentelemetry-operator-0-114-0-no-crds --non-interactive --namespace default

say "Upload the rendered objects to Space ${SPACE} (created on first upload)"
cub installer upload --work-dir ./open-telemetry-opentelemetry-operator-0-114-0-no-crds --space "${SPACE}"

say "Uploaded. See your Units:"
printf '  cub unit list --space %s\n  or open https://hub.confighub.com and find that Space.\n' "${SPACE}"

say "Next: create an environment variant and promote reviewed changes"
printf '  Walkthrough with the why behind each flag:\n  https://confighub.github.io/helm-expt/site/d/docs/user/variants-after-upload.html\n'

# Before applying this preset from ConfigHub to a cluster, it still needs:
#   - Secret default/opentelemetry-operator-controller-manager-service-cert keys tls.crt,tls.key (suggested: Run cert-manager controller to satisfy the chart-rendered Certificate, or stage a valid TLS Secret before waiting for the operator)
#   - CRD certificates.cert-manager.io (suggested: kubectl apply -f <crd-manifest.yaml>)
#   - CRD issuers.cert-manager.io (suggested: kubectl apply -f <crd-manifest.yaml>)
#   - CRD instrumentations.opentelemetry.io (suggested: kubectl apply -f <crd-manifest.yaml>)
#   - CRD opampbridges.opentelemetry.io (suggested: kubectl apply -f <crd-manifest.yaml>)
#   - CRD opentelemetrycollectors.opentelemetry.io (suggested: kubectl apply -f <crd-manifest.yaml>)
#   - CRD targetallocators.opentelemetry.io (suggested: kubectl apply -f <crd-manifest.yaml>)
